architecture Behavioral of ss_fsm_template is
  signal idle_state_eq, active_state_eq, done_state_eq, invalid_state_eq, enable_storage_o, force_idle_o, permit_state_o, startable_o, start_active_o, keep_active_o, finish_active_o, keep_done_o, not_finish_o, not_start_o, next_active_o, next_done_o, active_bit_o, done_bit_o : STD_LOGIC;
